/* Famili'Quiz — Espace & Univers */
QUIZ_DATA.add('espace', [
  // ===== Niveau 1 : 7-9 ans =====
  { l: 1, q: "Quelle étoile nous éclaire pendant la journée ?", a: ["Le Soleil", "La Lune", "L’étoile Polaire"], e: "☀️🌍", f: "Le Soleil est une étoile ! Sa lumière met environ 8 minutes pour arriver jusqu’à nous." },
  { l: 1, q: "Sur quelle planète vivons-nous ?", a: ["La Terre", "Mars", "Vénus", "Jupiter"], e: "🏠🌌", f: "La Terre est la seule planète connue qui abrite la vie : des plantes, des animaux… et nous !" },
  { l: 1, q: "Comment appelle-t-on une personne qui voyage dans l’espace ?", a: ["Un astronaute", "Un aviateur", "Un parachutiste", "Un plongeur"], e: "🚀🌌", f: "En Russie, on dit « cosmonaute » et en Chine « taïkonaute ». Tous ces mots désignent les voyageurs de l’espace !" },
  { l: 1, q: "Quelle planète est surnommée la « planète rouge » ?", a: ["Mars", "Jupiter", "Vénus", "Neptune"], e: "🔴🔭", f: "Mars est rouge parce que son sol contient beaucoup de fer rouillé. C’est une planète couverte de poussière de rouille !" },
  { l: 1, q: "Quel astre semble changer de forme au fil du mois ?", a: ["La Lune", "Le Soleil", "L’étoile Polaire"], e: "🌃👀", f: "Ce sont les « phases » de la Lune. Le cycle complet dure environ 29 jours et demi, presque un mois." },
  { l: 1, q: "Quel engin permet d’envoyer des astronautes dans l’espace ?", a: ["Une fusée", "Un hélicoptère", "Une montgolfière"], e: "👨‍🚀🌌", f: "Pour tourner autour de la Terre, il faut aller très vite : environ 28 000 km/h, plus de 30 fois plus vite qu’un avion de ligne !" },
  { l: 1, q: "Qui a été le premier homme à marcher sur la Lune ?", a: ["Neil Armstrong", "Thomas Pesquet", "Youri Gagarine", "Buzz l’Éclair"], e: "👣🌕", f: "C’était en juillet 1969. Il a dit : « C’est un petit pas pour l’homme, un bond de géant pour l’humanité. »" },
  { l: 1, q: "Quel astronaute français est parti deux fois vivre dans la Station spatiale ?", a: ["Thomas Pesquet", "Neil Armstrong", "Youri Gagarine", "Jules Verne"], e: "🛰️🥖", f: "Thomas Pesquet a passé près de 400 jours dans l’espace, pendant ses missions Proxima (2016-2017) et Alpha (2021)." },
  { l: 1, q: "Combien de planètes tournent autour de notre Soleil ?", a: ["8", "9", "7", "12"], e: "☀️🔢", f: "Pluton a longtemps été comptée comme la 9e planète, mais depuis 2006 les astronomes la rangent à part : elle est trop petite." },
  { l: 1, q: "Quelle est la plus grosse planète du système solaire ?", a: ["Jupiter", "Saturne", "La Terre", "Mars"], e: "🪐📏", f: "Jupiter est si énorme que plus de 1 000 Terres pourraient tenir à l’intérieur !" },
  { l: 1, q: "Quelle planète est entourée de magnifiques anneaux bien visibles ?", a: ["Saturne", "Mars", "Mercure"], e: "💍🔭", f: "Ses anneaux sont faits de milliards de morceaux de glace et de roche, certains aussi petits que des grains de sable." },
  { l: 1, q: "Comment appelle-t-on la Lune quand elle est toute ronde ?", a: ["La pleine lune", "La nouvelle lune", "Le premier quartier"], e: "🌃🔭", f: "À la pleine lune, la Lune est à l’opposé du Soleil : elle se lève à peu près quand le Soleil se couche." },
  { l: 1, q: "Que porte un astronaute pour sortir dans l’espace ?", a: ["Une combinaison spatiale", "Un ciré de pluie", "Une combinaison de plongée"], e: "👨‍🚀🛰️", f: "Elle protège du froid, de la chaleur et du vide, et fournit de l’air. Une combinaison de sortie pèse plus de 100 kg sur Terre !" },
  { l: 1, q: "Dans la Station spatiale, comment se déplacent les astronautes ?", a: ["Ils flottent", "Ils marchent normalement", "Ils glissent sur des patins"], e: "🛰️👀", f: "Sans pesanteur, ils se poussent du bout des doigts et s’accrochent à des poignées pour avancer." },
  { l: 1, q: "Quelle planète est la plus proche du Soleil ?", a: ["Mercure", "Vénus", "Mars", "Neptune"], e: "☀️🪐", f: "Mercure fait le tour du Soleil en seulement 88 jours. Une année y est bien plus courte que chez nous !" },
  { l: 1, q: "En combien d’heures environ la Terre fait-elle un tour sur elle-même ?", a: ["24 heures", "12 heures", "48 heures", "100 heures"], e: "🌍⏰", f: "C’est en tournant sur elle-même que la Terre nous fait passer du jour à la nuit : une moitié est éclairée, l’autre est dans l’ombre." },
  { l: 1, q: "Combien de temps met la Terre pour faire le tour du Soleil ?", a: ["Un an", "Un jour", "Un mois", "Une semaine"], e: "🌍☀️", f: "Il lui faut environ 365 jours et 6 heures. C’est pour ça qu’on ajoute un 29 février tous les 4 ans !" },
  { l: 1, q: "Une étoile filante, c’est en réalité…", a: ["Une poussière qui brûle dans l’air", "Une étoile qui tombe", "Un avion très rapide", "Une fusée qui décolle"], e: "🌠✨", f: "Ces poussières venues de l’espace chauffent tellement en traversant l’air qu’elles brillent. Elles sont souvent plus petites qu’un grain de sable !" },
  { l: 1, q: "Quel animal a été le premier à faire le tour de la Terre dans l’espace ?", a: ["Un chien", "Un chat", "Un singe", "Une souris"], e: "🚀🐾", f: "Elle s’appelait Laïka et a voyagé à bord du satellite soviétique Spoutnik 2, en novembre 1957." },
  { l: 1, q: "Comparé à la Terre, le Soleil est…", a: ["Beaucoup plus gros", "Plus petit", "De la même taille"], e: "☀️🌍", f: "On pourrait faire entrer environ 1,3 million de Terres dans le Soleil ! Il paraît petit parce qu’il est très loin." },
  { l: 1, q: "Comment appelle-t-on un groupe d’étoiles qui forme un dessin dans le ciel ?", a: ["Une constellation", "Une galaxie", "Une comète", "Une planète"], e: "✨🖍️", f: "La Grande Ourse est une constellation célèbre : ses sept étoiles les plus brillantes dessinent une grande casserole !" },
  { l: 1, q: "Comment s’appelle le véhicule à roues qui explore le sol de Mars ?", a: ["Un rover", "Un tracteur", "Un sous-marin"], e: "🔴🤖", f: "Le rover Perseverance explore Mars depuis 2021. Il a même emmené un petit hélicoptère, baptisé Ingenuity !" },
  { l: 1, q: "Où se trouve la Station spatiale internationale ?", a: ["Autour de la Terre", "Sur la Lune", "Sur Mars"], e: "🛰️❓", f: "Elle vole à environ 400 km au-dessus de nos têtes, à peu près la distance entre Paris et Lyon à vol d’oiseau !" },
  { l: 1, q: "Quel astre se trouve au centre de notre système solaire ?", a: ["Le Soleil", "La Terre", "La Lune", "Jupiter"], e: "🪐🎯", f: "Toutes les planètes tournent autour du Soleil. À lui seul, il contient plus de 99 % de la matière du système solaire !" },
  { l: 1, q: "Que se passe-t-il pendant une éclipse de Soleil ?", a: ["La Lune cache le Soleil", "Le Soleil s’éteint", "La Terre s’arrête de tourner"], e: "🕶️☀️", f: "Attention : on ne regarde jamais le Soleil sans lunettes spéciales, même pendant une éclipse. Des lunettes de soleil ne suffisent pas !" },
  { l: 1, q: "Comment dorment les astronautes dans la Station spatiale ?", a: ["Dans un sac de couchage accroché", "Dans un grand lit à étages", "Assis dans un fauteuil"], e: "💤🛰️", f: "Sans pesanteur, il n’y a ni haut ni bas ! Les astronautes s’attachent pour ne pas flotter et se cogner pendant leur sommeil." },
  { l: 1, q: "Comment boivent les astronautes dans la Station spatiale ?", a: ["Avec une paille dans une poche", "Dans un verre normal", "Dans un bol"], e: "💧🛰️", f: "Dans l’espace, l’eau ne coule pas : elle forme des boules qui flottent ! Il faut donc boire dans une poche fermée." },
  { l: 1, q: "Quel instrument permet d’observer les étoiles lointaines ?", a: ["Un télescope", "Un microscope", "Un périscope", "Un stéthoscope"], e: "👀✨", f: "Plus le miroir d’un télescope est grand, plus il capte de lumière. Les plus grands mesurent plus de 10 mètres de large !" },
  { l: 1, q: "De quelle couleur paraît surtout la Terre vue de l’espace ?", a: ["Bleue", "Rouge", "Jaune", "Violette"], e: "🛰️📷", f: "On l’appelle la « planète bleue » à cause de ses océans, qui recouvrent environ 70 % de sa surface." },
  { l: 1, q: "En s’approchant du Soleil, une comète forme une longue…", a: ["Queue", "Corne", "Antenne", "Aile"], e: "🔭☀️", f: "Une comète est une boule de glace et de poussière. Près du Soleil, sa glace se change en gaz, ce qui forme sa queue lumineuse." },
  { l: 1, q: "Peut-on parfois voir la Lune en plein jour ?", a: ["Oui", "Non, jamais", "Seulement en hiver"], e: "🌤️👀", f: "Oui ! On voit souvent la Lune le matin ou l’après-midi, quand elle n’est pas trop près du Soleil dans le ciel." },
  { l: 1, q: "Pourquoi ne voit-on pas les étoiles pendant la journée ?", a: ["Le Soleil brille trop fort", "Elles sont éteintes", "Elles se cachent derrière la Lune"], e: "⭐🌞", f: "Les étoiles sont toujours là, même le jour ! Mais la lumière du Soleil éclaire tellement le ciel qu’elle les cache." },
  { l: 1, q: "De quel côté le Soleil se lève-t-il ?", a: ["À l’est", "À l’ouest", "Au nord", "Au sud"], e: "🌅🧭", f: "Le Soleil se lève à l’est et se couche à l’ouest. En fait, il ne se déplace pas autour de nous : c’est la Terre qui tourne !" },
  { l: 1, q: "Dans l’espace, les toilettes fonctionnent un peu comme…", a: ["Un aspirateur", "Une chasse d’eau", "Une litière pour chat"], e: "🚽🛰️", f: "Sans pesanteur, rien ne tombe ! Les toilettes de l’espace aspirent tout avec un courant d’air." },
  { l: 1, q: "Le Soleil est une énorme boule de…", a: ["Gaz très chaud", "Glace", "Roche froide", "Lave"], e: "☀️🔎", f: "Sa surface atteint environ 5 500 °C et son cœur plus de 15 millions de degrés !" },
  { l: 1, q: "Sur la Lune, peut-on respirer sans casque ?", a: ["Non, il n’y a pas d’air", "Oui, l’air y est pur", "Oui, mais seulement la nuit"], e: "🌕👨‍🚀", f: "La Lune n’a pas d’atmosphère : pas d’air, pas de vent, pas de bruit. Les astronautes emportent leur propre air." },
  { l: 1, q: "Quelle forme a la Terre ?", a: ["Une boule", "Un disque plat", "Un cube"], e: "🚀📷", f: "Vue de l’espace, la Terre est presque une sphère parfaite, juste un peu aplatie aux pôles." },
  { l: 1, q: "Qui est le plus gros : la Terre ou la Lune ?", a: ["La Terre", "La Lune", "Elles ont la même taille"], e: "🌍🌕", f: "La Lune est presque 4 fois plus petite que la Terre en largeur." },
  { l: 1, q: "Comment appelle-t-on les astres qui tournent autour du Soleil, comme la Terre ?", a: ["Des planètes", "Des étoiles", "Des galaxies"], e: "☀️🔄", f: "Le mot « planète » vient du grec et veut dire « errante » : les Anciens les voyaient se promener parmi les étoiles." },
  { l: 1, q: "La Lune fabrique-t-elle sa propre lumière ?", a: ["Non, elle renvoie celle du Soleil", "Oui, comme une ampoule", "Oui, mais seulement l’hiver"], e: "🌃💡", f: "La Lune est un peu comme un miroir géant : elle renvoie vers nous une partie de la lumière du Soleil." },
  { l: 1, q: "Qu’ont planté les astronautes sur la Lune en 1969 ?", a: ["Un drapeau", "Un arbre", "Une tente"], e: "🌕📸", f: "Ils ont planté le drapeau des États-Unis. Le souffle du décollage l’a sûrement renversé quand ils sont repartis !" },
  { l: 1, q: "Selon les savants, qu’est-ce qui a fait disparaître les dinosaures ?", a: ["La chute d’un astéroïde", "Un morceau de Lune tombé", "Une explosion du Soleil", "Une pluie d’étoiles"], e: "🦖💥", f: "Il y a 66 millions d’années, un astéroïde d’environ 10 km s’est écrasé au Mexique. Nos oiseaux descendent des rares dinosaures qui ont survécu !" },
  { l: 1, q: "Combien de lunes la Terre possède-t-elle ?", a: ["Une seule", "Deux", "Aucune", "Trois"], e: "🌍🔢", f: "La Terre n’a qu’un satellite naturel, la Lune. C’est le 5e plus gros satellite du système solaire !" },
  { l: 1, q: "Lequel de ces appareils utilise des satellites pour trouver ton chemin ?", a: ["Le GPS", "Le micro-ondes", "La calculatrice"], e: "🛰️🚗", f: "Le GPS utilise une trentaine de satellites. Ton appareil calcule sa position grâce aux signaux d’au moins quatre d’entre eux." },
  { l: 1, q: "Pourquoi peut-on faire des bonds géants sur la Lune ?", a: ["On y pèse moins lourd", "Le sol est en caoutchouc", "Le vent nous pousse"], e: "🌕🤸", f: "Sur la Lune, on pèse environ 6 fois moins que sur Terre. Un enfant de 30 kg aurait l’impression d’en peser 5 !" },
  { l: 1, q: "De quoi la surface de la Lune est-elle couverte ?", a: ["De cratères", "De forêts", "De lacs", "De champs"], e: "🌕🔭", f: "Les cratères sont creusés par des météorites. Sans vent ni pluie pour les effacer, ils restent là des milliards d’années." },
  { l: 1, q: "Où voit-on le plus d’étoiles la nuit ?", a: ["À la campagne, loin des lumières", "En plein centre-ville", "Sous un lampadaire"], e: "🌃✨", f: "Les lumières des villes éclairent le ciel et cachent les étoiles. Loin de tout, on peut en voir des milliers à l’œil nu !" },
  { l: 1, q: "Pourquoi les astronautes font-ils du sport chaque jour dans l’espace ?", a: ["Pour garder des muscles solides", "Pour se réchauffer", "Pour faire avancer la station"], e: "🏋️🛰️", f: "Sans pesanteur, les muscles et les os s’affaiblissent vite. Les astronautes font environ 2 heures de sport par jour !" },
  { l: 1, q: "Comment appelle-t-on les savants qui étudient les étoiles ?", a: ["Les astronomes", "Les astrologues", "Les géologues", "Les biologistes"], e: "🔭👩‍🔬", f: "Attention à ne pas confondre : l’astronomie est une science, alors que l’astrologie prétend prédire l’avenir avec les astres." },
  { l: 1, q: "Quel est l’astre le plus brillant dans le ciel la nuit ?", a: ["La Lune", "L’étoile Polaire", "Mars", "Saturne"], e: "🌌👀", f: "La Lune est si proche de nous qu’une nuit de pleine lune, elle éclaire assez pour voir son ombre par terre !" },

  // ===== Niveau 2 : 10-12 ans =====
  { l: 2, q: "Comment s’appelle notre galaxie ?", a: ["La Voie lactée", "Andromède", "Le Grand Nuage de Magellan", "La galaxie du Sombrero"], e: "✨🏠", f: "Selon une légende grecque, du lait de la déesse Héra se serait répandu dans le ciel. « Galaxie » vient d’ailleurs du grec « gala », le lait !" },
  { l: 2, q: "Qui a été le premier être humain à voyager dans l’espace, en 1961 ?", a: ["Youri Gagarine", "Neil Armstrong", "Buzz Aldrin", "John Glenn"], e: "🚀🥇", f: "Le 12 avril 1961, le Soviétique Youri Gagarine a fait le tour de la Terre en 108 minutes à bord du vaisseau Vostok 1." },
  { l: 2, q: "Quelle planète a la surface la plus chaude du système solaire ?", a: ["Vénus", "Mercure", "Mars", "Jupiter"], e: "🌡️🪐", f: "Vénus n’est pas la plus proche du Soleil, mais son épaisse atmosphère piège la chaleur comme une serre : il y fait environ 460 °C !" },
  { l: 2, q: "Quelle planète est surnommée « l’étoile du berger » ?", a: ["Vénus", "Mars", "Jupiter", "Saturne"], e: "🐑✨", f: "Après la Lune, c’est l’astre le plus brillant de la nuit. On la voit le soir à l’ouest ou le matin à l’est." },
  { l: 2, q: "Quelle planète porte le nom du dieu romain de la guerre ?", a: ["Mars", "Jupiter", "Mercure", "Saturne"], e: "⚔️🛡️", f: "Sa couleur rouge rappelait le sang des batailles. Ses deux petites lunes s’appellent Phobos et Déimos : « peur » et « terreur » en grec !" },
  { l: 2, q: "Quel jour de la semaine doit son nom à la planète Mars ?", a: ["Mardi", "Mercredi", "Jeudi", "Vendredi"], e: "📅🔴", f: "Lundi vient de la Lune, mercredi de Mercure, jeudi de Jupiter et vendredi de Vénus. Samedi et dimanche ont d’autres origines." },
  { l: 2, q: "Quelle est la planète la plus éloignée du Soleil ?", a: ["Neptune", "Uranus", "Pluton", "Saturne"], e: "🔭❄️", f: "Il lui faut environ 165 ans pour faire le tour du Soleil. Depuis sa découverte en 1846, elle n’a bouclé qu’un seul tour !" },
  { l: 2, q: "Quelle est la plus petite planète du système solaire ?", a: ["Mercure", "Mars", "Vénus", "La Terre"], e: "🪐🔍", f: "Mercure est à peine plus grande que notre Lune. Sans vraie atmosphère, elle passe de 430 °C le jour à -180 °C la nuit !" },
  { l: 2, q: "Comment s’appelle le chemin que suit une planète autour du Soleil ?", a: ["Une orbite", "Un méridien", "Une éclipse", "Un équateur"], e: "🪐🔄", f: "Les orbites des planètes ne sont pas des cercles parfaits, mais des ellipses : des cercles un peu aplatis." },
  { l: 2, q: "Quelle direction indique l’étoile Polaire ?", a: ["Le nord", "Le sud", "L’est", "L’ouest"], e: "⭐🧭", f: "Elle se trouve presque exactement au-dessus du pôle Nord. On la trouve en prolongeant l’arrière de la « casserole » de la Grande Ourse." },
  { l: 2, q: "Comment s’appelle la célèbre famille de fusées européennes ?", a: ["Ariane", "Soyouz", "Falcon", "Saturn"], e: "🚀🌍", f: "La première fusée Ariane a décollé en 1979. Depuis 2024, c’est Ariane 6 qui a pris la relève." },
  { l: 2, q: "Depuis quel territoire français décollent les fusées Ariane ?", a: ["La Guyane", "La Réunion", "La Corse", "La Martinique"], e: "🚀🌴", f: "Le Centre spatial guyanais, à Kourou, est proche de l’équateur : la rotation de la Terre y donne un petit coup de pouce aux fusées." },
  { l: 2, q: "Comment s’appelait le tout premier satellite artificiel, lancé en 1957 ?", a: ["Spoutnik 1", "Apollo 1", "Hubble", "Vostok 1"], e: "🛰️📻", f: "C’était une boule de métal de 58 cm avec quatre antennes. Son « bip-bip » était capté par les radioamateurs du monde entier !" },
  { l: 2, q: "Depuis la Terre, que voit-on toujours de la Lune ?", a: ["La même face", "Une face différente chaque nuit", "Sa face cachée en hiver"], e: "🌕👀", f: "La Lune tourne sur elle-même à la même vitesse qu’elle tourne autour de nous. Sa face cachée n’a été photographiée qu’en 1959." },
  { l: 2, q: "De quelle couleur est le ciel sur la Lune, même en plein jour ?", a: ["Noir", "Bleu", "Rose"], e: "🌕🎨", f: "Sur Terre, l’air colore le ciel en bleu. La Lune n’a pas d’atmosphère : son ciel reste noir même quand le Soleil brille." },
  { l: 2, q: "Combien de temps mettaient les missions Apollo pour rejoindre la Lune ?", a: ["Environ 3 jours", "Environ 3 heures", "Environ 3 semaines", "Environ 3 mois"], e: "🚀⏳", f: "La Lune est à environ 384 000 km de la Terre. C’est comme faire près de dix fois le tour de notre planète !" },
  { l: 2, q: "Quelle mission a déposé les premiers hommes sur la Lune ?", a: ["Apollo 11", "Apollo 13", "Gemini 4", "Vostok 1"], e: "🌕👣", f: "L’équipage : Neil Armstrong, Buzz Aldrin et Michael Collins. Collins est resté en orbite pendant que les deux autres marchaient sur la Lune." },
  { l: 2, q: "Que trouve-t-on en très grand nombre entre Mars et Jupiter ?", a: ["Des astéroïdes", "Des comètes", "Des étoiles", "Des satellites artificiels"], e: "🔴🪐", f: "On parle de « ceinture d’astéroïdes ». Contrairement aux films, ces rochers sont très espacés : les sondes la traversent sans problème !" },
  { l: 2, q: "Depuis 2006, Pluton n’est plus une planète. Comment la classe-t-on ?", a: ["Une planète naine", "Un astéroïde géant", "Une comète", "Une lune de Neptune"], e: "❄️🔭", f: "Pluton est plus petite que notre Lune ! Pour être une vraie planète, il faut avoir « fait le ménage » autour de son orbite, ce qu’elle n’a pas fait." },
  { l: 2, q: "Sur quelle planète souffle la Grande Tache rouge, une tempête géante ?", a: ["Jupiter", "Mars", "Saturne", "Vénus"], e: "🌀🔴", f: "Cette tempête est plus large que la Terre entière, et les astronomes l’observent depuis près de 200 ans !" },
  { l: 2, q: "Que se passe-t-il pour la taille des astronautes dans l’espace ?", a: ["Ils grandissent un peu", "Ils rapetissent un peu", "Elle ne change pas"], e: "📏👨‍🚀", f: "Sans pesanteur, leur colonne vertébrale s’étire : ils peuvent gagner jusqu’à 5 cm ! Ils retrouvent leur taille au retour sur Terre." },
  { l: 2, q: "Pourquoi n’entend-on aucun bruit dans l’espace ?", a: ["Il n’y a pas d’air", "Il fait trop froid", "Les étoiles absorbent le bruit"], e: "🔇🌌", f: "Le son a besoin d’air, d’eau ou de matière pour voyager. Dans le vide spatial, même une énorme explosion serait silencieuse !" },
  { l: 2, q: "Quel célèbre télescope spatial tourne autour de la Terre depuis 1990 ?", a: ["Hubble", "James-Webb", "Kepler", "Herschel"], e: "🔭🛰️", f: "Il porte le nom de l’astronome Edwin Hubble. Des astronautes sont venus le réparer cinq fois grâce à la navette spatiale." },
  { l: 2, q: "Quel phénomène lumineux danse parfois dans le ciel près des pôles ?", a: ["Les aurores polaires", "Les étoiles filantes", "Les comètes", "Les éclipses"], e: "🌃❄️💚", f: "Elles naissent quand des particules envoyées par le Soleil heurtent le haut de notre atmosphère et la font briller, souvent en vert." },
  { l: 2, q: "Lors d’une éclipse de Lune, dans l’ombre de quel astre passe la Lune ?", a: ["La Terre", "Le Soleil", "Vénus", "Mars"], e: "🌕🌗", f: "Pendant une éclipse totale, la Lune ne disparaît pas : elle devient rouge cuivré. On parle parfois de « Lune de sang »." },
  { l: 2, q: "Comment s’appelle la phase où l’on ne voit presque pas la Lune ?", a: ["La nouvelle lune", "La pleine lune", "Le dernier quartier", "La lune gibbeuse"], e: "🌃❓", f: "À la nouvelle lune, la Lune passe entre la Terre et le Soleil : sa face éclairée est tournée de l’autre côté." },
  { l: 2, q: "Une année-lumière, c’est…", a: ["Une distance", "Une durée", "Une vitesse", "Une luminosité"], e: "💡⏳", f: "C’est la distance parcourue par la lumière en un an : environ 9 500 milliards de kilomètres !" },
  { l: 2, q: "Pourquoi un trou noir est-il noir ?", a: ["Même la lumière ne peut en sortir", "Il est couvert de poussière noire", "Il est caché par des planètes"], e: "🕳️🌌", f: "Un trou noir attire tout ce qui passe trop près. La toute première image d’un trou noir a été dévoilée en 2019." },
  { l: 2, q: "Où les astronautes s’entraînent-ils souvent aux sorties dans l’espace ?", a: ["Dans une immense piscine", "Dans une forêt", "Au sommet d’une montagne", "Dans un désert"], e: "👨‍🚀🎓", f: "Sous l’eau, bien lestés, ils flottent presque comme dans l’espace. La piscine d’entraînement de la NASA contient plus de 23 millions de litres !" },
  { l: 2, q: "Pourquoi les astronautes évitent-ils de manger du pain dans l’espace ?", a: ["Les miettes flotteraient partout", "Il moisit trop vite", "Il est trop lourd à emporter"], e: "🍞🛰️", f: "Les miettes pourraient se coincer dans les appareils ou dans les yeux. Les astronautes préfèrent les tortillas, des galettes sans miettes !" },
  { l: 2, q: "Quel héros de BD a marché sur la Lune 15 ans avant Neil Armstrong ?", a: ["Tintin", "Astérix", "Spirou", "Lucky Luke"], e: "📚🚀", f: "Dans « On a marché sur la Lune », paru en album en 1954, Hergé imagine une fusée à damier rouge et blanc devenue culte." },
  { l: 2, q: "La NASA est l’agence spatiale de quel pays ?", a: ["Les États-Unis", "La Russie", "Le Japon", "La Chine"], e: "🚀🏢", f: "La NASA a été créée en 1958, un an après le lancement de Spoutnik, en pleine course à l’espace contre l’URSS." },
  { l: 2, q: "Quel est le sigle de l’Agence spatiale européenne ?", a: ["ESA", "CNES", "NASA", "JAXA"], e: "🚀🤝", f: "L’ESA réunit plus de 20 pays et a son siège à Paris. Thomas Pesquet fait partie de ses astronautes." },
  { l: 2, q: "Quelle planète est si légère pour sa taille qu’elle flotterait dans une baignoire géante ?", a: ["Saturne", "Jupiter", "Mars", "La Terre"], e: "🛁🦆", f: "Saturne est surtout faite de gaz : elle est moins dense que l’eau ! Mais il faudrait une baignoire encore plus grande qu’elle…" },
  { l: 2, q: "Combien de temps dure en général une mission à bord de l’ISS ?", a: ["Environ 6 mois", "Environ 1 semaine", "Environ 3 ans", "Environ 1 jour"], e: "🛰️📆", f: "Le record d’affilée dans l’espace est de 437 jours, établi par le cosmonaute russe Valeri Poliakov en 1994-1995." },
  { l: 2, q: "Dans l’hémisphère Nord, comment s’appelle le jour le plus long de l’année ?", a: ["Le solstice d’été", "L’équinoxe de printemps", "Le solstice d’hiver", "Le jour de l’An"], e: "☀️📅", f: "Il tombe le 20, le 21 ou le 22 juin. Ce jour-là, à midi, le Soleil monte plus haut dans le ciel que n’importe quel autre jour." },
  { l: 2, q: "En partant du Soleil, à quelle place se trouve la Terre ?", a: ["3e", "2e", "4e", "5e"], e: "🌍🏅", f: "Astuce pour retenir l’ordre des planètes : « Me Voici Toute Mouillée, J’ai Suivi Un Nuage » (Mercure, Vénus, Terre, Mars…)." },
  { l: 2, q: "Comment appelle-t-on une pierre venue de l’espace tombée sur la Terre ?", a: ["Une météorite", "Une comète", "Une nébuleuse", "Un satellite"], e: "🌍💥", f: "Chaque jour, des tonnes de poussières venues de l’espace tombent sur la Terre, sans que personne ne les remarque !" },
  { l: 2, q: "La Station spatiale internationale est à peu près grande comme…", a: ["Un terrain de football", "Un bus", "Un court de tennis", "Une maison"], e: "🛰️📏", f: "L’ISS pèse environ 420 tonnes. On peut la voir à l’œil nu : un point très brillant qui traverse le ciel en quelques minutes." },
  { l: 2, q: "Quelle planète porte le nom du dieu romain des mers ?", a: ["Neptune", "Uranus", "Saturne", "Mercure"], e: "🔱🌊", f: "Elle est bleue grâce au méthane de son atmosphère. Des vents y soufflent à plus de 2 000 km/h, les plus rapides du système solaire !" },
  { l: 2, q: "Combien de levers de Soleil un astronaute de l’ISS peut-il voir en 24 heures ?", a: ["Environ 16", "Un seul", "Environ 4"], e: "🌅🛰️", f: "L’ISS fait le tour de la Terre en 1 h 30 environ : elle passe du jour à la nuit toutes les 45 minutes !" },
  { l: 2, q: "Comment appelle-t-on un immense regroupement de milliards d’étoiles ?", a: ["Une galaxie", "Une constellation", "Un système solaire", "Une comète"], e: "✨🔭", f: "Les astronomes estiment qu’il existe des centaines de milliards de galaxies dans l’Univers observable !" },
  { l: 2, q: "Quelle langue les astronautes de l’ISS doivent-ils apprendre en plus de l’anglais ?", a: ["Le russe", "Le chinois", "Le japonais", "L’allemand"], e: "🗣️🛰️", f: "De 2011 à 2020, les vaisseaux russes Soyouz étaient le seul moyen de rejoindre l’ISS. Thomas Pesquet parle russe !" },
  { l: 2, q: "Dans l’ISS, d’où vient une grande partie de l’eau que boivent les astronautes ?", a: ["De l’urine et de la sueur recyclées", "De la vapeur captée dans l’espace", "De livraisons quotidiennes"], e: "🚰🛰️", f: "Un système filtre l’urine, la sueur et l’humidité de l’air. Environ 98 % de l’eau est ainsi récupérée à bord !" },
  { l: 2, q: "Quand la partie éclairée de la Lune grandit chaque soir, on dit que la Lune est…", a: ["Croissante", "Décroissante", "Éclipsée"], e: "🌃📅", f: "Vue de France, quand elle forme un « D », elle croît ; quand elle forme un « C », elle décroît. On dit que « la Lune est menteuse » !" },
  { l: 2, q: "Comment appelle-t-on les planètes comme Jupiter et Saturne, faites surtout de gaz ?", a: ["Des géantes gazeuses", "Des planètes telluriques", "Des astéroïdes géants"], e: "🪐🧐", f: "Jupiter et Saturne n’ont pas de sol où se poser : une sonde s’enfoncerait dans des couches de gaz de plus en plus denses." },
  { l: 2, q: "Quel astre est le principal responsable des marées sur Terre ?", a: ["La Lune", "Le Soleil", "Mars", "Jupiter"], e: "🌊🏖️", f: "La Lune attire l’eau des océans. Quand elle est alignée avec le Soleil, à la pleine et à la nouvelle lune, on observe les grandes marées." },
  { l: 2, q: "Comment les astronautes se lavent-ils dans l’ISS ?", a: ["Avec des serviettes humides", "Sous une douche", "Dans une baignoire"], e: "🧼🛰️", f: "Il n’y a pas de douche dans l’ISS : l’eau flotterait partout ! Les astronautes utilisent des lingettes et un shampoing sans rinçage." },
  { l: 2, q: "Pour courir sur un tapis roulant dans l’ISS, de quoi l’astronaute a-t-il besoin ?", a: ["D’un harnais à élastiques", "De chaussures aimantées", "D’un casque spécial"], e: "🏃🛰️", f: "Sans les élastiques qui le tirent vers le tapis, l’astronaute s’envolerait au premier pas ! Il y a aussi un vélo et un appareil de musculation." },
  { l: 2, q: "Pourquoi une fusée est-elle composée de plusieurs étages ?", a: ["Pour larguer le poids inutile", "Pour transporter plus de passagers", "Pour aller moins vite"], e: "🚀🧩", f: "Une fois vides, les étages se détachent : la fusée s’allège et accélère plus facilement. Certains sont aujourd’hui récupérés et réutilisés." },

  // ===== Niveau 3 : 13-16 ans =====
  { l: 3, q: "Après le Soleil, quelle est l’étoile la plus proche de la Terre ?", a: ["Proxima du Centaure", "L’étoile Polaire", "Sirius", "Bételgeuse"], e: "⭐📏", f: "Elle est à environ 4,2 années-lumière : sa lumière met donc plus de 4 ans à nous parvenir. Elle n’est pas visible à l’œil nu !" },
  { l: 3, q: "Quelle constellation est célèbre pour les trois étoiles alignées de sa « ceinture » ?", a: ["Orion", "La Grande Ourse", "Cassiopée", "Le Cygne"], e: "✨🏹", f: "Orion est un chasseur géant de la mythologie grecque. Sous sa ceinture, on devine à l’œil nu la nébuleuse d’Orion, une pouponnière d’étoiles." },
  { l: 3, q: "Vers quel mois peut-on observer la pluie d’étoiles filantes des Perséides ?", a: ["Août", "Janvier", "Avril", "Octobre"], e: "🌠🗓️", f: "Chaque été, la Terre traverse les poussières laissées par la comète Swift-Tuttle. Le pic des Perséides a lieu vers le 12 août." },
  { l: 3, q: "Sur quelle planète se trouve Olympus Mons, le plus haut volcan connu du système solaire ?", a: ["Mars", "Vénus", "La Terre", "Mercure"], e: "🌋🏔️", f: "Ce volcan géant s’élève à plus de 20 km : plus de deux fois la hauteur de l’Everest !" },
  { l: 3, q: "Que signifie le mot « astronaute », formé à partir du grec ?", a: ["Navigateur des astres", "Marcheur du ciel", "Voyageur du temps", "Gardien des étoiles"], e: "🏛️⛵", f: "« Astron » signifie « astre » et « nautês » « navigateur ». Les Russes disent « cosmonaute » : navigateur du cosmos." },
  { l: 3, q: "Quelle forme a notre galaxie, la Voie lactée ?", a: ["Une spirale", "Une boule", "Un anneau", "Une forme irrégulière"], e: "🌌🔭", f: "C’est une galaxie spirale barrée. Le Soleil se trouve dans l’un de ses bras, à environ 26 000 années-lumière du centre." },
  { l: 3, q: "Quelle mission Apollo a dû renoncer à se poser sur la Lune après l’explosion d’un réservoir ?", a: ["Apollo 13", "Apollo 11", "Apollo 8", "Apollo 17"], e: "💥🚀", f: "En 1970, les trois astronautes sont rentrés sains et saufs en utilisant le module lunaire comme canot de sauvetage. Un film en a été tiré en 1995." },
  { l: 3, q: "Comment s’appelle le programme de la NASA qui doit ramener des humains sur la Lune ?", a: ["Artemis", "Gemini", "Mercury", "Skylab"], e: "🌕🔜", f: "Artémis est la sœur jumelle d’Apollon dans la mythologie grecque : un clin d’œil au programme Apollo. Le premier vol, sans équipage, a eu lieu en 2022." },
  { l: 3, q: "Comment s’appelait le petit robot européen qui s’est posé sur une comète en 2014 ?", a: ["Philae", "Huygens", "Curiosity", "Spirit"], e: "☄️🤖", f: "Largué par la sonde Rosetta, Philae a rebondi deux fois avant de s’immobiliser sur la comète Tchourioumov-Guérassimenko." },
  { l: 3, q: "Quel savant a découvert en 1610 quatre lunes de Jupiter grâce à sa lunette ?", a: ["Galilée", "Copernic", "Kepler", "Newton"], e: "🔭🪐", f: "Io, Europe, Ganymède et Callisto sont depuis appelées les « lunes galiléennes ». Elles prouvaient que tout ne tourne pas autour de la Terre !" },
  { l: 3, q: "Quelle sonde, lancée en 1977, est l’objet humain le plus éloigné de la Terre ?", a: ["Voyager 1", "Pioneer 10", "New Horizons", "Voyager 2"], e: "🛰️🌌", f: "Elle est entrée dans l’espace interstellaire en 2012. Ses signaux mettent aujourd’hui près d’une journée à nous parvenir !" },
  { l: 3, q: "Quelle comète célèbre revient près de la Terre environ tous les 76 ans ?", a: ["Halley", "Hale-Bopp", "Shoemaker-Levy 9", "Swift-Tuttle"], e: "☄️🔁", f: "Elle est passée pour la dernière fois en 1986 et reviendra en 2061. L’écrivain Mark Twain est né et mort lors de deux de ses passages !" },
  { l: 3, q: "Dans quelle ville se trouve le centre de contrôle des vols habités de la NASA ?", a: ["Houston", "New York", "Washington", "Miami"], e: "📞🚀", f: "C’est pour cela que les astronautes s’adressent à « Houston » à la radio. Les fusées, elles, décollent de Floride, au cap Canaveral." },
  { l: 3, q: "Quel vaisseau américain réutilisable a volé de 1981 à 2011 ?", a: ["La navette spatiale", "Saturn V", "Soyouz", "Vostok"], e: "🛩️🚀", f: "Les navettes ont réalisé 135 missions. Elles ont notamment servi à lancer le télescope Hubble et à assembler l’ISS." },
  { l: 3, q: "Qu’appelle-t-on une exoplanète ?", a: ["Une planète autour d’une autre étoile", "Une planète sans atmosphère", "Une planète qui a perdu sa lune", "Une planète faite de glace"], e: "🔭🌍", f: "La première autour d’une étoile semblable au Soleil a été découverte en 1995 par les Suisses Michel Mayor et Didier Queloz, prix Nobel 2019." },
  { l: 3, q: "Comment appelle-t-on l’explosion spectaculaire d’une étoile massive en fin de vie ?", a: ["Une supernova", "Une nébuleuse", "Une naine blanche", "Une aurore"], e: "💥⭐", f: "Une supernova peut briller autant que toute une galaxie. Le fer de notre sang a été fabriqué dans des étoiles !" },
  { l: 3, q: "Quelle est l’étoile la plus brillante du ciel nocturne ?", a: ["Sirius", "L’étoile Polaire", "Bételgeuse", "Véga"], e: "✨🏆", f: "Sirius, dans la constellation du Grand Chien, n’est qu’à 8,6 années-lumière. L’étoile Polaire, elle, est loin d’être la plus brillante !" },
  { l: 3, q: "Quelle planète tourne sur elle-même presque couchée sur le côté ?", a: ["Uranus", "Neptune", "Saturne", "Mars"], e: "🪐🛌", f: "Son axe est incliné d’environ 98°. Résultat : chaque pôle connaît environ 42 ans de jour, puis 42 ans de nuit !" },
  { l: 3, q: "Quelle planète a la journée la plus courte, avec moins de 10 heures ?", a: ["Jupiter", "Mercure", "La Terre", "Neptune"], e: "⏱️🪐", f: "Jupiter fait un tour sur elle-même en 9 h 56 environ. Cette rotation rapide l’aplatit nettement aux pôles." },
  { l: 3, q: "Comment s’appelle la plus grande lune de Saturne, entourée d’une épaisse atmosphère ?", a: ["Titan", "Europe", "Io", "Triton"], e: "🌫️🪐", f: "Titan possède des lacs et des mers… de méthane liquide ! La sonde européenne Huygens s’y est posée en 2005." },
  { l: 3, q: "Combien de temps environ Mars met-elle pour faire le tour du Soleil ?", a: ["Près de 2 ans", "6 mois", "1 an pile", "12 ans"], e: "🔴🗓️", f: "Une année martienne dure 687 jours terrestres : les saisons y sont environ deux fois plus longues que chez nous." },
  { l: 3, q: "Avec les fusées actuelles, combien de temps faut-il environ pour rejoindre Mars ?", a: ["6 à 9 mois", "3 jours", "3 semaines", "5 ans"], e: "🚀🔴", f: "Il faut partir au bon moment, quand la Terre et Mars sont bien placées : ces « fenêtres de tir » reviennent environ tous les 26 mois." },
  { l: 3, q: "Combien d’astronautes ont marché sur la Lune entre 1969 et 1972 ?", a: ["12", "2", "6", "24"], e: "👨‍🚀🔢", f: "Tous américains, ils sont venus lors de six missions Apollo. Le dernier, Eugene Cernan, a quitté la Lune en décembre 1972." },
  { l: 3, q: "Qui a été la première femme à voyager dans l’espace, en 1963 ?", a: ["Valentina Terechkova", "Claudie Haigneré", "Sally Ride", "Svetlana Savitskaïa"], e: "👩‍🚀🥇", f: "Le 16 juin 1963, elle a passé près de 3 jours en orbite à bord de Vostok 6. Elle n’avait que 26 ans !" },
  { l: 3, q: "Qui est la première Française à être allée dans l’espace, en 1996 ?", a: ["Claudie Haigneré", "Sophie Adenot", "Samantha Cristoforetti", "Julie Payette"], e: "👩‍🚀🥖", f: "Médecin rhumatologue, elle a volé deux fois dans l’espace (1996 et 2001), puis est devenue ministre déléguée à la Recherche." },
  { l: 3, q: "Qui a été le premier Français à voyager dans l’espace, en 1982 ?", a: ["Jean-Loup Chrétien", "Thomas Pesquet", "Patrick Baudry", "Léopold Eyharts"], e: "👨‍🚀🥖", f: "Il a rejoint la station soviétique Saliout 7. En 1988, il est devenu le premier astronaute ni américain ni soviétique à sortir dans l’espace." },
  { l: 3, q: "Quelle grande galaxie voisine peut-on apercevoir à l’œil nu depuis la France ?", a: ["Andromède", "Le Sombrero", "Le Tourbillon", "M87"], e: "🌌👀", f: "Elle est à environ 2,5 millions d’années-lumière : la lumière qu’on en voit est partie à l’époque des premiers ancêtres du genre humain !" },
  { l: 3, q: "De quelle couleur sont les étoiles les plus chaudes ?", a: ["Bleues", "Rouges", "Orange", "Jaunes"], e: "⭐🌡️", f: "Les étoiles rouges sont les plus « froides » (environ 3 000 °C) ; les bleues peuvent dépasser 30 000 °C. Notre Soleil est entre les deux." },
  { l: 3, q: "Comment s’appelait la fusée géante du programme Apollo ?", a: ["Saturn V", "Ariane 5", "Soyouz", "Falcon 9"], e: "🚀🌕", f: "Haute de 110 mètres, Saturn V reste l’une des fusées les plus puissantes jamais construites." },
  { l: 3, q: "Quelle constellation dessine un grand « W » dans le ciel ?", a: ["Cassiopée", "Orion", "Le Cygne", "La Lyre"], e: "✨🔠", f: "Dans la mythologie grecque, Cassiopée était une reine si vaniteuse qu’elle fut punie par Poséidon, le dieu des mers." },
  { l: 3, q: "Sur la Lune, combien de temps dure une nuit environ ?", a: ["Environ 2 semaines", "Environ 12 heures", "Environ 1 heure", "Environ 6 mois"], e: "🌕🌃", f: "Une journée lunaire complète dure environ 29 jours et demi : deux semaines de jour brûlant, puis deux semaines de nuit glaciale." },
  { l: 3, q: "Combien d’étoiles compte environ la Voie lactée ?", a: ["Plus de 100 milliards", "Environ 1 million", "Environ 8 000", "Environ 50 000"], e: "🌌🔢", f: "Les astronomes l’estiment entre 100 et 400 milliards. Le Soleil n’est qu’une étoile parmi toutes celles-ci !" },
  { l: 3, q: "Quel âge a environ notre Soleil ?", a: ["4,6 milliards d’années", "460 millions d’années", "46 millions d’années", "4 600 ans"], e: "☀️🎂", f: "Il est à peu près à la moitié de sa vie. Dans environ 5 milliards d’années, il gonflera pour devenir une géante rouge." },
  { l: 3, q: "Où se trouve le télescope spatial James-Webb ?", a: ["À 1,5 million de km de la Terre", "En orbite à 400 km d’altitude", "Sur la face cachée de la Lune", "En orbite autour de Mars"], e: "🔭✨", f: "Lancé le 25 décembre 2021 par une Ariane 5, il observe l’infrarouge et doit rester très froid, à l’abri derrière un immense pare-soleil." },
  { l: 3, q: "Quel objet insolite la fusée Falcon Heavy a-t-elle emporté dans l’espace lors de son premier vol, en 2018 ?", a: ["Une voiture de sport", "Un piano à queue", "Une cabine téléphonique", "Un vélo de course"], e: "🚀🎁", f: "Une Tesla Roadster rouge, avec au volant un mannequin en combinaison baptisé « Starman ». Elle tourne désormais autour du Soleil." },
  { l: 3, q: "Comment s’appelle le point du ciel situé exactement au-dessus de notre tête ?", a: ["Le zénith", "Le nadir", "L’horizon", "Le méridien"], e: "🔭🌌", f: "Le point opposé, sous nos pieds, s’appelle le nadir. Être « au zénith », c’est être au sommet de sa gloire !" },
  { l: 3, q: "Lors d’un équinoxe, qu’ont de particulier le jour et la nuit ?", a: ["Ils durent à peu près autant", "Le jour est le plus long de l’année", "La nuit est la plus longue de l’année", "La Lune est forcément pleine"], e: "🗓️☀️", f: "« Équinoxe » vient du latin et signifie « nuit égale ». Il y en a deux par an, vers le 20 mars et vers le 22 septembre." },
  { l: 3, q: "Dans quelle direction pointe la queue d’une comète ?", a: ["À l’opposé du Soleil", "Vers le Soleil", "Vers la Terre", "Vers le centre de la galaxie"], e: "☄️🧭", f: "Le vent solaire et la lumière du Soleil « soufflent » la queue. Quand la comète s’éloigne du Soleil, sa queue passe donc devant elle !" },
  { l: 3, q: "Pourquoi les astronautes flottent-ils à bord de l’ISS ?", a: ["Ils sont en chute libre permanente", "Il n’y a plus de gravité à 400 km", "L’air de la station les soulève", "La Lune les attire vers le haut"], e: "🛰️🎈", f: "À 400 km d’altitude, la gravité vaut encore environ 90 % de celle du sol ! La station et ses occupants « tombent » ensemble autour de la Terre." },
  { l: 3, q: "Quelle est la distance moyenne entre la Terre et le Soleil ?", a: ["Environ 150 millions de km", "Environ 384 000 km", "Environ 15 millions de km", "Environ 1,5 milliard de km"], e: "🌍📏☀️", f: "Cette distance sert d’unité aux astronomes : l’unité astronomique (ua). Neptune, par exemple, est à environ 30 ua du Soleil." },
  { l: 3, q: "Chez les Romains, qui était Mercure, qui a donné son nom à une planète ?", a: ["Le messager des dieux", "Le dieu de la guerre", "Le roi des dieux", "Le dieu des mers"], e: "🏛️👟", f: "Les Anciens ont donné ce nom à la planète qui se déplace le plus vite dans le ciel, comme un messager pressé." },
  { l: 3, q: "Quel élément chimique compose environ les trois quarts de la masse du Soleil ?", a: ["L’hydrogène", "L’hélium", "Le carbone", "Le fer"], e: "☀️🧪", f: "Dans son cœur, le Soleil transforme chaque seconde environ 600 millions de tonnes d’hydrogène en hélium !" },
  { l: 3, q: "Pourquoi les taches solaires paraissent-elles sombres ?", a: ["Elles sont moins chaudes qu’autour", "Ce sont des trous dans le Soleil", "Ce sont des planètes devant lui", "Elles sont couvertes de cendres"], e: "☀️🔍", f: "Elles sont « seulement » à environ 4 000 °C, contre 5 500 °C autour. Leur nombre varie selon un cycle d’environ 11 ans." },
  { l: 3, q: "Combien de constellations officielles se partagent le ciel ?", a: ["88", "12", "48", "365"], e: "✨🗺️", f: "Leur liste a été fixée en 1922 par l’Union astronomique internationale. 48 d’entre elles avaient déjà été décrites par Ptolémée, dans l’Antiquité." },
  { l: 3, q: "Sur Mars, quelle impression de poids aurait une personne de 50 kg ?", a: ["Environ 19 kg", "Environ 8 kg", "Environ 50 kg", "Environ 130 kg"], e: "🔴⚖️", f: "La pesanteur martienne vaut environ 38 % de celle de la Terre : on y sauterait environ 2,5 fois plus haut !" },
  { l: 3, q: "Que sont les « mers » que l’on voit sur la Lune ?", a: ["Des plaines de lave refroidie", "De vraies étendues d’eau", "Des déserts de sable", "Des forêts pétrifiées"], e: "🌕🌊", f: "Les premiers astronomes les ont prises pour des mers. Apollo 11 s’est posé dans la mer de la Tranquillité." },
  { l: 3, q: "Sous quelle forme trouve-t-on aujourd’hui beaucoup d’eau sur Mars ?", a: ["De la glace", "Des océans liquides", "Des nuages de pluie", "Des rivières"], e: "🔴💧", f: "Ses calottes polaires contiennent beaucoup de glace d’eau. Des vallées asséchées montrent que de l’eau liquide y coulait il y a des milliards d’années." },
  { l: 3, q: "De quoi sont faits les épais nuages qui entourent Vénus ?", a: ["D’acide sulfurique", "De vapeur d’eau", "De poussière de fer", "De neige carbonique"], e: "☁️🪐", f: "Ces nuages renvoient très bien la lumière du Soleil : c’est ce qui rend Vénus si brillante dans notre ciel." },
  { l: 3, q: "Comment s’appelait la station spatiale soviétique, puis russe, en orbite de 1986 à 2001 ?", a: ["Mir", "Saliout 7", "Skylab", "Tiangong"], e: "🛰️🕰️", f: "« Mir » signifie à la fois « paix » et « monde » en russe. Elle a accueilli plusieurs astronautes français." },
  { l: 3, q: "À bord de quel vaisseau Thomas Pesquet a-t-il rejoint l’ISS en 2021 ?", a: ["Crew Dragon", "Soyouz", "La navette spatiale", "Orion"], e: "🚀🛰️", f: "Pour sa première mission, en 2016, il avait décollé à bord d’un Soyouz russe, depuis le cosmodrome de Baïkonour." },

  // ===== Niveau 4 : Adultes =====
  { l: 4, q: "Qui a réalisé la toute première sortie dans l’espace, en 1965 ?", a: ["Alexeï Leonov", "Youri Gagarine", "Ed White", "Neil Armstrong"], e: "👨‍🚀🚪", f: "Sa combinaison avait tellement gonflé dans le vide qu’il a dû en laisser échapper de l’air pour réussir à rentrer dans le sas !" },
  { l: 4, q: "Quel animal la France a-t-elle envoyé dans l’espace en octobre 1963 ?", a: ["Une chatte", "Une chienne", "Un lapin", "Une tortue"], e: "🐾🚀", f: "Elle s’appelait Félicette. Le 18 octobre 1963, elle a atteint environ 157 km d’altitude lors d’un vol d’une quinzaine de minutes." },
  { l: 4, q: "Quel pays est devenu en 2003 le troisième à envoyer un humain dans l’espace par ses propres moyens ?", a: ["La Chine", "L’Inde", "Le Japon", "La France"], e: "🚀🥉", f: "Yang Liwei a fait 14 fois le tour de la Terre à bord de Shenzhou 5, le 15 octobre 2003." },
  { l: 4, q: "Quel exploit la mission chinoise Chang’e 4 a-t-elle réalisé en 2019 ?", a: ["Se poser sur la face cachée de la Lune", "Ramener des roches de Mars", "Poser un taïkonaute sur la Lune", "Atteindre l’orbite de Vénus"], e: "🌑🤖", f: "Elle y a déposé le petit rover Yutu-2. Chang’e est la déesse de la Lune dans la mythologie chinoise." },
  { l: 4, q: "Quelle planète met plus de temps à tourner sur elle-même qu’à faire le tour du Soleil ?", a: ["Vénus", "Mercure", "Mars", "Uranus"], e: "⏳🪐", f: "Vénus met 243 jours terrestres à tourner sur elle-même, mais seulement 225 à faire le tour du Soleil. Et elle tourne à l’envers !" },
  { l: 4, q: "Quelle lune de Jupiter est l’astre le plus volcanique du système solaire ?", a: ["Io", "Europe", "Ganymède", "Callisto"], e: "🌋🌑", f: "Io compte des centaines de volcans actifs, chauffés par les gigantesques effets de marée de Jupiter. Certains panaches montent à plus de 300 km !" },
  { l: 4, q: "Quelle est la plus grosse lune du système solaire ?", a: ["Ganymède", "Titan", "La Lune", "Triton"], e: "🌑🏆", f: "Ganymède, autour de Jupiter, est plus grande que la planète Mercure ! C’est aussi la seule lune connue à avoir son propre champ magnétique." },
  { l: 4, q: "Quelle lune de Saturne projette des geysers d’eau dans l’espace ?", a: ["Encelade", "Titan", "Mimas", "Japet"], e: "⛲🪐", f: "Découverts par la sonde Cassini en 2005, ces jets proviennent d’un océan d’eau salée caché sous sa croûte de glace." },
  { l: 4, q: "Quelle est la planète la plus dense du système solaire ?", a: ["La Terre", "Jupiter", "Mercure", "Vénus"], e: "⚖️🪐", f: "Avec 5,5 g/cm³, la Terre devance de peu Mercure. Saturne, elle, est moins dense que l’eau !" },
  { l: 4, q: "À quelle altitude place-t-on souvent la frontière de l’espace, appelée « ligne de Kármán » ?", a: ["100 km", "10 km", "1 000 km", "36 000 km"], e: "📏🌍", f: "Les avions de ligne volent vers 10 km d’altitude. Les États-Unis, eux, décernent le titre d’astronaute dès 80 km environ." },
  { l: 4, q: "Selon la théorie la plus admise, comment la Lune s’est-elle formée ?", a: ["Par une collision géante avec la Terre", "Capturée par la gravité terrestre", "En même temps que la Terre, à côté", "Éjectée par un volcan terrestre"], e: "🌍💥🌕", f: "Il y a environ 4,5 milliards d’années, un astre de la taille de Mars, baptisé Théia, aurait percuté la jeune Terre." },
  { l: 4, q: "Dans quelle région lointaine, au-delà de Neptune, se trouve Pluton ?", a: ["La ceinture de Kuiper", "La ceinture d’astéroïdes", "Le nuage d’Oort", "La ceinture de Van Allen"], e: "❄️🔭", f: "Cette ceinture glacée porte le nom de l’astronome Gerard Kuiper. Elle abrite des milliers d’objets connus, dont plusieurs planètes naines." },
  { l: 4, q: "Quelle sonde a survolé Pluton pour la première fois, en 2015 ?", a: ["New Horizons", "Voyager 2", "Cassini", "Rosetta"], e: "🛰️❤️", f: "Elle a révélé un immense glacier en forme de cœur, baptisé Tombaugh Regio en l’honneur de Clyde Tombaugh, qui a découvert Pluton en 1930." },
  { l: 4, q: "Quel astronome français a découvert Neptune par le calcul, en 1846 ?", a: ["Urbain Le Verrier", "Charles Messier", "Camille Flammarion", "Pierre-Simon de Laplace"], e: "🧮🔭", f: "Il a déduit sa position des perturbations de l’orbite d’Uranus. L’Allemand Galle l’a ensuite repérée en moins d’une heure de recherche !" },
  { l: 4, q: "Quel astronome a découvert la planète Uranus en 1781 ?", a: ["William Herschel", "Galilée", "Johannes Kepler", "Edmond Halley"], e: "🔭🎶", f: "C’était la première planète découverte au télescope. Herschel voulait l’appeler « l’étoile de George », en l’honneur du roi George III !" },
  { l: 4, q: "Que deviendra notre Soleil à la toute fin de sa vie ?", a: ["Une naine blanche", "Un trou noir", "Une étoile à neutrons", "Une supernova"], e: "☀️🔮", f: "Il n’est pas assez massif pour exploser. Après sa phase de géante rouge, il deviendra un petit astre très dense, de la taille de la Terre." },
  { l: 4, q: "Selon les estimations actuelles, quel est l’âge de l’Univers ?", a: ["Environ 13,8 milliards d’années", "Environ 4,6 milliards d’années", "Environ 100 milliards d’années", "Environ 1 million d’années"], e: "🌌⏳", f: "Cet âge est notamment déduit des mesures du satellite européen Planck, qui a cartographié la plus vieille lumière de l’Univers." },
  { l: 4, q: "Quelle supergéante rouge marque l’épaule d’Orion ?", a: ["Bételgeuse", "Rigel", "Aldébaran", "Antarès"], e: "🔴⭐", f: "Si elle remplaçait le Soleil, elle engloutirait les orbites de Mercure, de Vénus, de la Terre et de Mars !" },
  { l: 4, q: "Comment s’appelle le trou noir supermassif situé au centre de la Voie lactée ?", a: ["Sagittarius A*", "M87*", "Cygnus X-1", "Alpha du Centaure"], e: "🕳️🎯", f: "Il pèse environ 4 millions de fois la masse du Soleil. Sa première image a été dévoilée en 2022 par la collaboration Event Horizon Telescope." },
  { l: 4, q: "De combien la Lune s’éloigne-t-elle de la Terre chaque année ?", a: ["Environ 3,8 cm", "Environ 3,8 mm", "Environ 3,8 m", "Environ 38 km"], e: "🌕↔️", f: "On le mesure grâce à des tirs laser vers des réflecteurs déposés sur la Lune par les missions Apollo et les robots soviétiques Lunokhod." },
  { l: 4, q: "À quelle altitude orbitent les satellites géostationnaires, qui semblent immobiles dans le ciel ?", a: ["Environ 36 000 km", "Environ 400 km", "Environ 3 600 km", "Environ 360 000 km"], e: "📡🛰️", f: "À cette altitude, un satellite fait le tour de la Terre en un jour, au rythme exact de sa rotation : idéal pour la télévision !" },
  { l: 4, q: "Quel astronome allemand a énoncé, au début du XVIIe siècle, trois lois sur le mouvement des planètes ?", a: ["Johannes Kepler", "Galilée", "Tycho Brahe", "Ptolémée"], e: "🪐📜", f: "Il s’est appuyé sur les observations très précises de Tycho Brahe. Ses lois ont ensuite aidé Newton à expliquer la gravitation." },
  { l: 4, q: "Comment s’appelait le module lunaire d’Apollo 11 ?", a: ["Eagle", "Columbia", "Falcon", "Snoopy"], e: "🚀🌕", f: "« Houston, ici la base de la Tranquillité. L’Aigle s’est posé. » Columbia était le module de commande resté en orbite." },
  { l: 4, q: "Dans la mythologie, quel lien unit Saturne à Jupiter ?", a: ["Saturne est son père", "Saturne est son fils", "Saturne est son frère", "Saturne est son épouse"], e: "🏛️👑", f: "Saturne correspond au titan grec Cronos, qui dévorait ses enfants. Le jeune Jupiter (Zeus) lui a échappé, puis l’a détrôné." },
  { l: 4, q: "Comment s’appelle la couche visible du Soleil, celle qui émet sa lumière ?", a: ["La photosphère", "La chromosphère", "La couronne", "L’héliopause"], e: "☀️🔬", f: "La couronne, l’atmosphère extérieure du Soleil, est bien plus chaude : plus d’un million de degrés ! Un mystère encore étudié." },
  { l: 4, q: "Combien de temps la lumière de la Lune met-elle pour nous parvenir ?", a: ["Un peu plus d’une seconde", "Environ 8 minutes", "Environ 1 heure", "Environ 1 jour"], e: "🌕💡", f: "Lors des missions Apollo, chaque échange radio entre la Terre et la Lune subissait donc environ 2,5 secondes de délai aller-retour." },
  { l: 4, q: "Quelle unité de distance vaut environ 3,26 années-lumière ?", a: ["Le parsec", "L’unité astronomique", "Le mégamètre", "Le mille marin"], e: "📏✨", f: "Dans « Star Wars », Han Solo se vante d’un record en « moins de 12 parsecs »… alors que c’est une distance, pas une durée !" },
  { l: 4, q: "Quel astronaute, premier Américain à faire le tour de la Terre en 1962, est retourné dans l’espace à 77 ans ?", a: ["John Glenn", "Alan Shepard", "Buzz Aldrin", "Gus Grissom"], e: "👴🚀", f: "En 1998, il a volé à bord de la navette Discovery, alors qu’il était sénateur. Alan Shepard, lui, avait été le premier Américain dans l’espace en 1961." },
  { l: 4, q: "Quel prêtre et astronome belge est considéré comme le père de la théorie du Big Bang ?", a: ["Georges Lemaître", "Edwin Hubble", "Stephen Hawking", "Carl Sagan"], e: "💥🌌", f: "Dès 1927, il propose que l’Univers est en expansion. En 1931, il imagine un « atome primitif » d’où tout serait né." },
  { l: 4, q: "Quelles galaxies naines, visibles depuis l’hémisphère Sud, portent le nom d’un navigateur ?", a: ["Les Nuages de Magellan", "Les Nuages de Colomb", "Les Nuages de Cook", "Les Nuages de Vasco de Gama"], e: "⛵🌌", f: "L’expédition de Magellan les a décrites lors du premier tour du monde (1519-1522), mais les peuples du Sud les connaissaient bien avant." },
  { l: 4, q: "Comment les scientifiques appellent-ils un jour martien, qui dure environ 24 h 40 ?", a: ["Un sol", "Un mars", "Un orbe", "Un cycle"], e: "🔴⏰", f: "Les équipes qui pilotent les rovers vivent parfois à l’heure martienne : leurs horaires se décalent alors d’environ 40 minutes chaque jour !" },
  { l: 4, q: "Sur quelle heure les horloges de l’ISS sont-elles réglées ?", a: ["Le temps universel (UTC)", "L’heure de Houston", "L’heure de Moscou", "L’heure de Paris"], e: "🕒🛰️", f: "C’est un compromis pratique entre les centres de contrôle de Houston et de Moscou, situés sur des fuseaux horaires très différents." },
  { l: 4, q: "Quelle constellation, traversée par le Soleil, ne fait pas partie des 12 signes du zodiaque ?", a: ["Le Serpentaire", "Orion", "Pégase", "Andromède"], e: "☀️🔭", f: "Le Soleil passe devant le Serpentaire (Ophiuchus) de fin novembre à mi-décembre. Les signes astrologiques ne collent plus aux vraies constellations." },
  { l: 4, q: "Le Soleil est environ 400 fois plus large que la Lune. Il est aussi environ… plus loin de nous.", a: ["400 fois", "40 fois", "4 000 fois", "4 fois"], e: "🌑☀️", f: "Cette coïncidence permet à la Lune de recouvrir presque exactement le Soleil lors des éclipses totales." },
  { l: 4, q: "Quelle planète a été percutée en 1994 par les fragments de la comète Shoemaker-Levy 9 ?", a: ["Jupiter", "Saturne", "Mars", "Vénus"], e: "☄️💥", f: "Une vingtaine de fragments s’y sont écrasés en une semaine, laissant dans son atmosphère des taches sombres plus grandes que la Terre." },
  { l: 4, q: "Comment s’appelait le premier satellite français, lancé en 1965 ?", a: ["Astérix", "Obélix", "Diamant", "Spot"], e: "🛰️🥖", f: "Lancé par la fusée Diamant, il a fait de la France la troisième puissance spatiale, après l’URSS et les États-Unis." },
  { l: 4, q: "En quelle année le CNES, l’agence spatiale française, a-t-il été créé ?", a: ["1961", "1945", "1975", "1990"], e: "🚀🏛️", f: "Il a été créé sous la présidence du général de Gaulle. Son siège est à Paris et son grand centre technique se trouve à Toulouse." },
  { l: 4, q: "Quel est environ le diamètre de notre galaxie, la Voie lactée ?", a: ["100 000 années-lumière", "1 000 années-lumière", "10 millions d’années-lumière", "100 années-lumière"], e: "🌌📏", f: "Le Soleil met environ 230 millions d’années à en faire le tour. Depuis sa naissance, il n’a donc fait qu’une vingtaine de tours !" },
  { l: 4, q: "Quel physicien britannique a montré que les trous noirs pourraient lentement « s’évaporer » ?", a: ["Stephen Hawking", "Isaac Newton", "Paul Dirac", "Peter Higgs"], e: "🕳️🧠", f: "Ce « rayonnement de Hawking » a été proposé en 1974. Il est aussi l’auteur du best-seller « Une brève histoire du temps » (1988)." },
  { l: 4, q: "Comment appelle-t-on la limite d’un trou noir au-delà de laquelle rien ne peut ressortir ?", a: ["L’horizon des événements", "La ligne de Kármán", "L’héliopause", "La limite de Roche"], e: "🕳️🚧", f: "Pour un trou noir ayant la masse du Soleil, cet horizon ne mesurerait qu’environ 3 km de rayon !" },
  { l: 4, q: "Quel écrivain a imaginé dès 1865 un voyage vers la Lune à bord d’un obus tiré par un canon géant ?", a: ["Jules Verne", "Victor Hugo", "H. G. Wells", "Alexandre Dumas"], e: "📚🌕", f: "Dans « De la Terre à la Lune », le canon est installé en Floride… non loin de l’endroit d’où décolleront les fusées Apollo un siècle plus tard !" },
  { l: 4, q: "Dans quel pays se trouve le cosmodrome de Baïkonour ?", a: ["Le Kazakhstan", "La Russie", "L’Ukraine", "La Mongolie"], e: "🚀🏜️", f: "La Russie le loue au Kazakhstan. C’est de là que sont partis Spoutnik 1 en 1957 et Youri Gagarine en 1961." },
  { l: 4, q: "Les célèbres « Piliers de la création » photographiés par Hubble sont des colonnes de…", a: ["Gaz et poussière", "Glace", "Roche", "Lave"], e: "🔭🏛️", f: "Ils se trouvent dans la nébuleuse de l’Aigle. De nouvelles étoiles sont en train de naître à l’intérieur !" },
  { l: 4, q: "À quelle vitesse approximative la Terre file-t-elle autour du Soleil ?", a: ["Environ 107 000 km/h", "Environ 1 700 km/h", "Environ 300 km/h", "Environ 1 million de km/h"], e: "🌍💨", f: "Soit environ 30 km par seconde ! À l’équateur, la rotation de la Terre sur elle-même nous fait aussi filer à près de 1 700 km/h." },
  { l: 4, q: "Comment appelle-t-on le point de l’orbite d’une planète le plus proche du Soleil ?", a: ["Le périhélie", "L’aphélie", "L’apogée", "Le zénith"], e: "🪐☀️", f: "La Terre passe au périhélie début janvier, à environ 147 millions de km du Soleil, contre 152 millions début juillet." },
  { l: 4, q: "Comment appelle-t-on la faible lueur qui éclaire la partie sombre d’un fin croissant de Lune ?", a: ["La lumière cendrée", "La lumière zodiacale", "Le rayon vert", "Le halo lunaire"], e: "🌒✨", f: "C’est la lumière du Soleil renvoyée par la Terre vers la Lune. Léonard de Vinci a été l’un des premiers à l’expliquer." },
  { l: 4, q: "Sur quelle célèbre œuvre médiévale voit-on la comète de Halley, en 1066 ?", a: ["La tapisserie de Bayeux", "La Dame à la licorne", "Les Très Riches Heures", "Le Livre de Kells"], e: "☄️🧵", f: "Elle y apparaît quelques mois avant la bataille d’Hastings. Les témoins de l’époque y voyaient un mauvais présage pour le roi Harold." },
  { l: 4, q: "En astronomie, que mesure la « magnitude » d’une étoile ?", a: ["Son éclat", "Sa masse", "Sa température", "Son âge"], e: "⭐📊", f: "L’échelle est inversée : plus la magnitude est faible, plus l’astre est brillant. Sirius atteint -1,46, et le Soleil environ -27 !" },
  { l: 4, q: "Quelle est la plus grande planète naine connue, par son diamètre ?", a: ["Pluton", "Cérès", "Éris", "Makémaké"], e: "❄️📏", f: "Éris, découverte en 2005, est un peu plus massive, mais Pluton, avec environ 2 377 km de diamètre, est légèrement plus grande." },
  { l: 4, q: "Que sont les Pléiades, visibles dans la constellation du Taureau ?", a: ["Un amas d’étoiles", "Une galaxie", "Une comète", "Une nébuleuse planétaire"], e: "🐂✨", f: "On les surnomme les « Sept Sœurs ». Au Japon, elles s’appellent Subaru, comme la marque automobile qui les a sur son logo !" }
]);
